def column_totals(rows):
    if not rows:
        return []
    result = []
    for i in range(len(rows[0])):
        total = 0
        has_numeric = False
        for r in rows:
            try:
                # Try to convert to float to handle numeric strings
                val = float(r[i])
                total += val
                has_numeric = True
            except (ValueError, TypeError):
                # Ignore non-numeric values
                pass
        if has_numeric:
            # If the total is an integer, keep it as int for cleaner output
            if total.is_integer():
                total = int(total)
            result.append(total)
        else:
            result.append("")
    return result

